package app.qalm.ink

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs

/**
 * The Kotlin perfect-freehand port must give the same outline as @qalm/core `strokeOutline` (perfect-freehand in JS).
 * The fixture is generated by scripts/gen-freehand-fixture.ts (`pnpm --filter qalm-ink gen:fixture`).
 */
class QalmFreehandTest {
  private class Case(val name: String, val tool: String, val width: Double, val pts: List<InkPoint>, val out: List<DoubleArray>)

  private fun load(): List<Case> {
    val lines = javaClass.classLoader!!.getResourceAsStream("freehand-fixture.txt")!!.bufferedReader().readLines()
    val cases = ArrayList<Case>()
    var i = 0
    fun nums() = lines[i++].trim().split(' ').map { it.toDouble() }
    while (i < lines.size) {
      if (lines[i].isBlank()) { i++; continue }
      val (_, name, tool, width) = lines[i++].split(' ')
      val n = lines[i++].removePrefix("pts ").toInt()
      val pts = (0 until n).map { val v = nums(); InkPoint(v[0], v[1], v[2], v[3], 0.0, 0.0) }
      val m = lines[i++].removePrefix("out ").toInt()
      val out = (0 until m).map { nums().toDoubleArray() }
      cases.add(Case(name, tool, width.toDouble(), pts, out))
    }
    return cases
  }

  @Test
  fun matchesCoreOutlines() {
    val cases = load()
    assertTrue(cases.size >= 5)
    for (c in cases) {
      val got = QalmFreehand.outline(c.tool, c.width, c.pts)
      assertEquals("${c.name}: outline length", c.out.size, got.size)
      for (k in got.indices) {
        for (d in 0..1) {
          // Math.hypot / sin / cos may differ from V8 in the last ulp.
          assertTrue("${c.name}[$k][$d]: ${got[k][d]} vs ${c.out[k][d]}", abs(got[k][d] - c.out[k][d]) < 1e-9)
        }
      }
    }
  }
}
